local({
  w <- coalesce(
    as.numeric(CH97PRWT),
    as.numeric(CH02PRWT),
    as.numeric(CH07PRWT),
    as.numeric(X14CHWGT),
    if_else(.wave == "2020", as.numeric(X19CVWGT), as.numeric(X19CHWGT))
  )
  if_else(w > 0, w, NA_real_)
})

local({
  s <- if_else(.wave == "1997", paste0("1997_", sprintf("%.0f", as.numeric(DEMID97))), NA_character_)
  coalesce(carry_within(s, participant_id, order = as.numeric(.wave)), family_unit)
})

local({
  c97 <- as.numeric(CHRACE)
  i97 <- case_when(c97 == 5 ~ "Indigenous", c97 %in% c(1, 2, 3, 4, 7) ~ "Non-Indigenous", .default = NA_character_)
  recs <- sapply(1:4, function(k) {
    r1 <- as.numeric(coalesce(tbl[[paste0("X14RAC1", k)]], tbl[[paste0("X19RAC1", k)]]))
    r2 <- as.numeric(coalesce(tbl[[paste0("X14RAC2", k)]], tbl[[paste0("X19RAC2", k)]]))
    case_when(
      r1 == 3 & !(r2 %in% c(1:5, 7)) ~ "Indigenous",
      r1 %in% c(1:5, 7) ~ "Non-Indigenous",
      .default = NA_character_
    )
  })
  obs <- coalesce(i97, apply(recs, 1, function(r) r[!is.na(r)][1]))
  coalesce(carry_within(obs, participant_id, order = as.numeric(.wave)), "Unknown")
})

