local({
  m <- sapply(c("L17", "L18"), function(stem) {
    v <- sapply(c("A", "B", "C", "D", "E", "F", "G", "H", "I", "J"), function(l) {
      x <- as.numeric(coalesce(tbl[[paste0("Q23", stem, l)]], tbl[[paste0("Q33", stem, l)]]))
      x <- if_else(x %in% 1:3, x, NA_real_)
      if (l %in% c("C", "E", "F", "H")) x else 4 - x
    })
    rowMeans(v)
  })
  x <- rowMeans(m, na.rm = TRUE)
  if_else(is.nan(x), NA_real_, x)
})

local({
  h97 <- if_else(as.numeric(IMPUTED1) <= 13, as.numeric(HOME1), NA_real_)
  age02 <- as.numeric(Q21IWAGE)
  h02 <- case_when(age02 < 6 ~ as.numeric(HT1_02), age02 < 10 ~ as.numeric(HT2_02), age02 >= 10 ~ as.numeric(HT3_02))
  coalesce(h97, h02, as.numeric(HT3_07))
})

local({
  c97 <- if_else(as.numeric(COGIMP) <= 7, as.numeric(COGSCALE), NA_real_)
