  c02 <- case_when(age02 < 6 ~ as.numeric(CG1_02), age02 < 10 ~ as.numeric(CG2_02), age02 >= 10 ~ as.numeric(CG3_02))
  coalesce(c97, c02, as.numeric(CG3_07))
})

