local({
  con <- sapply(c("E", "M", "S", "W", "rG"), function(l) {
    rv <- substr(l, 1, 1) == "r" & nchar(l) > 1
    k <- if (rv) substring(l, 2) else l
    ks <- if (k %in% c("S", "W")) paste0(k, c("1", "2")) else k
    v <- sapply(ks, function(kk) {
      as.numeric(coalesce(tbl[[paste0("P19B1", kk)]], tbl[[paste0("P20CVB1", kk)]]))
    })
    v[!(v %in% 1:3)] <- NA
    v <- apply(matrix(v, nrow = nrow(tbl)), 1, function(r) r[!is.na(r)][1])
    if (rv) 3 - v else v - 1
  })
  con <- if_else(rowSums(!is.na(con)) >= 3, floor(rowMeans(con, na.rm = TRUE) * 5 + 0.5), NA_real_)
  con
})

