  x <- as.numeric(coalesce(Q1A10, Q21A2, P14A5, P19A5))
  obs <- recode_values(x, 1 ~ "TRUE", 5 ~ "FALSE", default = NA_character_)
  carry_within(obs, participant_id, order = as.numeric(.wave))
})

